31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.security.core.Authentication;
46	import org.springframework.security.core.context.SecurityContextHolder;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        owner.setCity(resolveCity(owner.getCity()));
114	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
115	        owner.setCustomerCode(buildCustomerCode(owner.getCity()));
116	        owner.setMembershipTier(resolveMembershipTier());
117	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
118	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
119	        owner.setLocality(resolveLocality(owner.getCity()));
120	        long areaCodeMatches = countAreaCodeMatches(owner.getTelephone());
121	        this.clinicService.saveOwner(owner);
122	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
123	            currentUsername(), owner.getId(), owner.getMembershipNumber());
124	        if (areaCodeMatches >= BULK_SIGNUP_AREA_CODE_THRESHOLD) {
125	            AUDIT.warn("Possible bulk signup: ownerId={} telephone={} shares area code with {} existing owners",
126	                owner.getId(), owner.getTelephone(), areaCodeMatches);
127	        }
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    /**
135	     * The name of the currently authenticated user, or {@code "anonymous"} if
136	     * there is no authentication in the security context.
137	     */
138	    private String currentUsername() {
139	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
140	        return authentication != null ? authentication.getName() : "anonymous";
141	    }
142	
143	    /**
144	     * Resolve the city for a newly created owner. If an owner already exists in
145	     * that city (matched case-insensitively), reuse that owner's exact spelling;
146	     * otherwise the supplied city is title-cased.
147	     */
148	    private String resolveCity(String city) {
149	        if (city == null) {
150	            return null;
151	        }
152	        return this.clinicService.findAllOwners().stream()
153	            .map(Owner::getCity)
154	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
155	            .findFirst()
156	            .orElseGet(() -> titleCase(city));
157	    }
158	
159	    /**
160	     * Title-case a city name: the first letter of each whitespace-separated word
161	     * is upper-cased and the remaining letters lower-cased.
162	     */
163	    private String titleCase(String city) {
164	        StringBuilder sb = new StringBuilder(city.length());
165	        boolean startOfWord = true;
166	        for (int i = 0; i < city.length(); i++) {
167	            char c = city.charAt(i);
168	            if (Character.isWhitespace(c)) {
169	                startOfWord = true;
170	                sb.append(c);
171	            } else if (startOfWord) {
172	                sb.append(Character.toUpperCase(c));
173	                startOfWord = false;
174	            } else {
175	                sb.append(Character.toLowerCase(c));
176	            }
177	        }
178	        return sb.toString();
179	    }
180	
181	    /**
182	     * The number of owners that, once created, are granted the 'FOUNDING'
183	     * membership tier. Owners created after this threshold receive 'STANDARD'.
184	     */
185	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
186	
187	    /**
188	     * Resolve the membership tier for a newly created owner: the first
189	     * {@link #FOUNDING_MEMBERSHIP_LIMIT} owners ever created are 'FOUNDING' and
190	     * all later owners are 'STANDARD'.
191	     */
192	    private String resolveMembershipTier() {
193	        long existingOwners = this.clinicService.findAllOwners().size();
194	        return existingOwners < FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD";
195	    }
196	
197	    /**
198	     * Build the customer code for a newly created owner, formatted as
199	     * '<UPPERCASE_CITY>-<NNNN>' where NNNN is one more than the number of owners
200	     * that already exist in that city, zero-padded to four digits.
201	     */
202	    private String buildCustomerCode(String city) {
203	        long ownersInCity = this.clinicService.findAllOwners().stream()
204	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
205	            .count();
206	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
207	    }
208	
209	    /**
210	     * Count how many owners already exist that share the given last name
211	     * (compared case-insensitively) at the moment a new owner is created.
212	     */
213	    private int countNamesakes(String lastName) {
214	        if (lastName == null) {
215	            return 0;
216	        }
217	        return (int) this.clinicService.findAllOwners().stream()
218	            .filter(existing -> existing.getLastName() != null
219	                && existing.getLastName().equalsIgnoreCase(lastName))
220	            .count();
221	    }
222	
223	    /**
224	     * Determine whether another owner already shares a household with a newly
225	     * created owner, i.e. an existing owner already has the same address and city
226	     * (both compared case-insensitively) at the moment the new owner is created.
227	     */
228	    private boolean sharesHousehold(String address, String city) {
229	        if (address == null || city == null) {
230	            return false;
231	        }
232	        return this.clinicService.findAllOwners().stream()
233	            .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
234	                && city.equalsIgnoreCase(existing.getCity()));
235	    }
236	
237	    /**
238	     * Resolve the locality for a newly created owner: 'local' if the owner's city
239	     * is the single most common city among the owners that already exist at the
240	     * moment the new owner is created, otherwise 'remote'. Cities are compared
241	     * case-insensitively. If no owners yet exist, or two or more cities are tied
242	     * for the most common, there is no single most common city and the result is
243	     * 'remote'.
244	     */
245	    private String resolveLocality(String city) {
246	        if (city == null) {
247	            return "remote";
248	        }
249	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
250	            .map(Owner::getCity)
251	            .filter(Objects::nonNull)
252	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(), Collectors.counting()));
253	        if (countsByCity.isEmpty()) {
254	            return "remote";
255	        }
256	        long maxCount = countsByCity.values().stream().max(Long::compareTo).orElse(0L);
257	        long citiesWithMax = countsByCity.values().stream().filter(count -> count == maxCount).count();
258	        boolean cityIsMostCommon = countsByCity.getOrDefault(city.toLowerCase(), 0L) == maxCount;
259	        return citiesWithMax == 1 && cityIsMostCommon ? "local" : "remote";
260	    }
261	
262	    /**
263	     * The number of existing owners that must share a newly created owner's
264	     * telephone area code before a possible bulk signup is flagged.
265	     */
266	    private static final int BULK_SIGNUP_AREA_CODE_THRESHOLD = 5;
267	
268	    /**
269	     * Count how many existing owners share the given telephone's area code (its
270	     * first three digits) at the moment a new owner is created. If the telephone
271	     * is null or has fewer than three digits there is no area code and the result
272	     * is zero.
273	     */
274	    private long countAreaCodeMatches(String telephone) {
275	        String areaCode = areaCode(telephone);
276	        if (areaCode == null) {
277	            return 0;
278	        }
279	        return this.clinicService.findAllOwners().stream()
280	            .map(existing -> areaCode(existing.getTelephone()))
281	            .filter(areaCode::equals)
282	            .count();
283	    }
284	
285	    /**
286	     * The area code of a telephone, i.e. its first three characters, or
287	     * {@code null} if the telephone is null or shorter than three characters.
288	     */
289	    private String areaCode(String telephone) {
290	        if (telephone == null || telephone.length() < 3) {
291	            return null;
292	        }
293	        return telephone.substring(0, 3);
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
299	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
300	        if (currentOwner == null) {
301	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	        }
303	        currentOwner.setAddress(ownerFieldsDto.getAddress());
304	        currentOwner.setCity(ownerFieldsDto.getCity());
305	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
306	        currentOwner.setLastName(ownerFieldsDto.getLastName());
307	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
308	        currentOwner.setEmail(ownerFieldsDto.getEmail());
309	        this.clinicService.saveOwner(currentOwner);
310	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
311	    }
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Transactional
315	    @Override
316	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
317	        Owner owner = this.clinicService.findOwnerById(ownerId);
318	        if (owner == null) {
319	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	        }
321	        this.clinicService.deleteOwner(owner);
322	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
328	        Owner owner = this.clinicService.findOwnerById(ownerId);
329	        if (owner == null) {
330	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
331	        }
332	        HttpHeaders headers = new HttpHeaders();
333	        Pet pet = petMapper.toPet(petFieldsDto);
334	        owner.setId(ownerId);
335	        pet.setOwner(owner);
336	        pet.getType().setName(null);
337	        this.clinicService.savePet(pet);
338	        PetDto petDto = petMapper.toPetDto(pet);
339	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
340	            .buildAndExpand(pet.getId()).toUri());
341	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
342	    }
343	
344	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
345	    @Override
346	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
347	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
348	        if (currentOwner != null) {
349	            Pet currentPet = this.clinicService.findPetById(petId);
350	            if (currentPet != null) {
351	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
352	                currentPet.setName(petFieldsDto.getName());
353	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
354	                this.clinicService.savePet(currentPet);
355	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
356	            }
357	        }
358	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
364	        HttpHeaders headers = new HttpHeaders();
365	        Visit visit = visitMapper.toVisit(visitFieldsDto);
366	        Pet pet = new Pet();
367	        pet.setId(petId);
368	        visit.setPet(pet);
369	        this.clinicService.saveVisit(visit);
370	        VisitDto visitDto = visitMapper.toVisitDto(visit);
371	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
372	            .buildAndExpand(visit.getId()).toUri());
373	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
374	    }
375	
376	
377	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
378	    @Override
379	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
380	        Owner owner = this.clinicService.findOwnerById(ownerId);
381	        if (owner != null) {
382	            Pet pet = owner.getPet(petId);
383	            if (pet != null) {
384	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
385	            }
386	        }
387	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
388	    }
389	}
