private boolean isDuplicateTelephone(Owner owner) {
    if (owner.getTelephone() == null) {
        return false;
    }
    String telephone = normalizeKey(owner.getTelephone());
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> !existing.getId().equals(owner.getId())
            && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
}

/**
 * The maximum number of owners that may be registered on a single calendar day (by registration
 * date). Attempts to register more than this in a day are rejected.
 */
private static final long MAX_OWNERS_PER_DAY = 20;

private boolean dailyRegistrationLimitReached(LocalDate registrationDate) {
    if (registrationDate == null) {
        return false;
    }
    long registeredOnDay = ownerRepository.findAll().stream()
        .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
        .count();
    return registeredOnDay >= MAX_OWNERS_PER_DAY;
}

/**
 * The maximum number of owners that may reside in a single city. Once a city already contains
 * this many owners, attempts to register a further owner in that city are rejected.
 */
private static final long MAX_OWNERS_PER_CITY = 8;

private boolean cityOwnerLimitReached(Owner owner) {
    if (owner.getCity() == null) {
        return false;
    }
    String city = normalizeKey(owner.getCity());
    long ownersInCity = ownerRepository.findAll().stream()
        .filter(existing -> !existing.getId().equals(owner.getId())
            && Objects.equals(normalizeKey(existing.getCity()), city))
        .count();
    return ownersInCity >= MAX_OWNERS_PER_CITY;
}

private boolean isDuplicateOwner(Owner owner) {
    if (owner.getLastName() == null) {
        return false;
    }
    String lastName = normalizeKey(owner.getLastName());
    String telephone = normalizeKey(owner.getTelephone());
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> !existing.getId().equals(owner.getId())
            && Objects.equals(normalizeKey(existing.getLastName()), lastName)
            && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
}

/**
 * Normalizes a value for duplicate detection so that comparisons ignore
 * letter case and surrounding or repeated whitespace (e.g. {@code
 * "  john   smith "} and {@code "John Smith"} are treated as equal).
 */
private static String normalizeKey(String value) {
    if (value == null) {
        return null;
    }
    return value.trim().replaceAll("\\s+", " ").toLowerCase();
}

@Override
@Transactional(readOnly = true)
public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
    return ownerRepository.findByLastName(lastName);
}

@Override
@Transactional(readOnly = true)
public Collection<Visit> findVisitsByPetId(int petId) {
    return visitRepository.findByPetId(petId);
}
